parameters.jsCode:
// Summarize next ~12 hours from Open-Meteo hourly arrays
const hourly = $json.hourly;

const times = hourly.time;
const temps = hourly.temperature_2m;
const precip = hourly.precipitation;
const clouds = hourly.cloudcover;
const wind = hourly.windspeed_10m;

const n = Math.min(12, times.length);

let maxTemp = -Infinity;
let minTemp = Infinity;
let totalPrecip = 0;
let maxPrecip = 0;
let avgCloud = 0;
let maxWind = 0;

for (let i = 0; i < n; i++) {
  const t = temps[i];
  const p = precip[i];
  const c = clouds[i];
  const w = wind[i];

  if (t > maxTemp) maxTemp = t;
  if (t < minTemp) minTemp = t;

  totalPrecip += p;
  if (p > maxPrecip) maxPrecip = p;

  avgCloud += c;
  if (w > maxWind) maxWind = w;
}

avgCloud = avgCloud / n;

// Simple labels for planning
const rainy = totalPrecip >= 2 || maxPrecip >= 1;      // mm thresholds (rough)
const windy = maxWind >= 25;                           // km/h rough
const cold = maxTemp <= 5;                             // °C
const hot = maxTemp >= 28;                             // °C

let weatherLabel = "great_outdoors";
if (rainy) weatherLabel = "rainy";
else if (cold) weatherLabel = "cold";
else if (hot) weatherLabel = "hot";
else if (windy) weatherLabel = "windy";

return [{
  json: {
    next_hours: n,
    temp_c_min: Number(minTemp.toFixed(1)),
    temp_c_max: Number(maxTemp.toFixed(1)),
    precip_mm_total: Number(totalPrecip.toFixed(2)),
    precip_mm_max_hour: Number(maxPrecip.toFixed(2)),
    cloud_avg_pct: Number(avgCloud.toFixed(0)),
    wind_kmh_max: Number(maxWind.toFixed(1)),
    weather_label: weatherLabel
  }
}];

const lat0 = Number($node["Prepare Places Query"].json.lat);
const lon0 = Number($node["Prepare Places Query"].json.lon);

// Better error handling: check if elements exists and is an array
const elements = Array.isArray($json.elements) ? $json.elements : [];

// If no valid elements, return empty array with error info
if (!elements.length) {
  return [{
    json: {
      deduped: [],
      error: "No elements found in API response",
      raw_response: $json
    }
  }];
}

function haversineMiles(lat1, lon1, lat2, lon2) {
  const R = 3958.8; // Earth radius in miles
  const toRad = d => (d * Math.PI) / 180;
  const dLat = toRad(lat2 - lat1);
  const dLon = toRad(lon2 - lon1);
  const a =
    Math.sin(dLat/2)**2 +
    Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon/2)**2;
  return 2 * R * Math.asin(Math.sqrt(a));
}

function getLatLon(el) {
  if (typeof el.lat === "number" && typeof el.lon === "number") return { lat: el.lat, lon: el.lon };
  if (el.center && typeof el.center.lat === "number" && typeof el.center.lon === "number") return { lat: el.center.lat, lon: el.center.lon };
  return null;
}

const places = elements.map(el => {
  const tags = el.tags || {};
  const coords = getLatLon(el);
  if (!coords) return null;

  const name = tags.name || null;
  const amenity = tags.amenity || null;

  // keep only relevant items (amenity based)
  if (!amenity) return null;

  const distance_miles = haversineMiles(lat0, lon0, coords.lat, coords.lon);

  return {
    name: name || `${amenity}`,
    amenity,
    lat: coords.lat,
    lon: coords.lon,
    distance_miles: Number(distance_miles.toFixed(1)),
    // optional address hints if available
    city: tags["addr:city"] || null,
    street: tags["addr:street"] || null,
    website: tags.website || tags["contact:website"] || null
  };
}).filter(Boolean);

// Deduplicate by (name + rounded coords)
const seen = new Set();
const deduped = [];
for (const p of places) {
  const key = `${(p.name || "").toLowerCase()}|${p.lat.toFixed(5)}|${p.lon.toFixed(5)}`;
  if (seen.has(key)) continue;
  seen.add(key);
  deduped.push(p);
}

// Sort by distance
deduped.sort((a,b) => a.distance_miles - b.distance_miles);

return [{
  json: {
    deduped
  }
}];

// Get the places array from the collect places node output
const places = Array.isArray($json.places) ? $json.places : [];

// Pull context from the input
const weatherLabel = String($json.weather_label ?? "cold").toLowerCase();
const dayType = String($json.day_type ?? "weekday").toLowerCase();
const groupSize = Number($json.group_size ?? 4);

// scoring helpers
const chainKeywords = [
  "starbucks","mcdonald","subway","taco bell","domino",
  "pizza hut","little caesars","panera","jimmy john",
  "dairy queen","noodles & company","buffalo wild wings"
];

function chainPenalty(name) {
  const n = (name || "").toLowerCase();
  return chainKeywords.some(k => n.includes(k)) ? 0.25 : 0;
}

function amenityBoost(amenity) {
  const a = (amenity || "").toLowerCase();
  if (a === "restaurant") return 0.25;
  if (a === "pub") return 0.22;
  if (a === "bar") return 0.20;
  if (a === "cafe") return 0.15;
  if (a === "fast_food") return -0.10;
  return 0;
}

function distancePenalty(dMiles) {
  return Math.min(0.4, Number(dMiles || 0) / 40);
}

function crowdRisk(amenity) {
  let risk = 0.25;
  const a = (amenity || "").toLowerCase();
  if (a === "bar" || a === "pub") risk += 0.25;
  if (a === "restaurant") risk += 0.20;
  return Math.max(0, Math.min(1, risk));
}

function groupFit(amenity) {
  const a = (amenity || "").toLowerCase();
  let score = groupSize <= 2 ? 0.9 : groupSize <= 5 ? 0.82 : 0.7;
  if (a === "cafe" && groupSize >= 6) score -= 0.15;
  if (a === "fast_food" && groupSize >= 6) score -= 0.10;
  return Math.max(0, Math.min(1, score));
}

function weatherFit() {
  return ["cold","rainy","snowy","windy"].includes(weatherLabel) ? 0.9 : 0.85;
}

const scored_places = places
  .filter(p => p && p.name) // keep valid
  .map(p => {
    const cr = crowdRisk(p.amenity);
    const gf = groupFit(p.amenity);
    const wf = weatherFit();

    const score =
      (0.35 * gf) +
      (0.25 * wf) +
      (0.20 * (1 - cr)) +
      amenityBoost(p.amenity) -
      chainPenalty(p.name) -
      distancePenalty(p.distance_miles);

    return {
      ...p,
      crowd_risk: Number(cr.toFixed(2)),
      group_fit: Number(gf.toFixed(2)),
      weather_fit: Number(wf.toFixed(2)),
      score: Number(score.toFixed(3)),
    };
  })
  .sort((a, b) => b.score - a.score);

// Return ONE item containing the full ranked list
return [{
  json: {
    weather_label: weatherLabel,
    day_type: dayType,
    group_size: groupSize,
    scored_places
  }
}];

