=Context:
- Weather: {{$json.weather_label}}
- Day type: {{$json.day_type}}
- Group size: {{$json.group_size}}

Candidate places (ranked):
{{$json.top5}}

Task:
Pick the best 3 options for today. For each option:
- 1 sentence what it is
- 2 bullets why it fits (group size + weather + crowd)
- Mention distance and rating if available
- Give a simple “best time to go” suggestion

Return as JSON with keys:
{ "top_recommendations": [...], "why_these": "...", "backup": [...] }

parameters.jsCode:
const scored = $json.scored_places || [];
const top5 = scored.slice(0, 5);
const backup5 = scored.slice(5, 10);

return [{
  json: {
    ...$json,
    top5,
    backup5
  }
}];

function stripCodeFences(s) {
  if (!s) return "";
  // remove ```json ... ``` or ``` ... ```
  return s
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();
}

// Depending on your LLM node, the text may be in different fields.
// Common cases:
const raw =
  $json.text ||
  $json.response ||
  $json.output ||
  $json.message ||
  ($json.generations?.[0]?.[0]?.text) ||
  "";

const cleaned = stripCodeFences(String(raw));

// Try to parse JSON; if it fails, still return cleaned text so you can see errors.
let parsed = null;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {}

return [{
  json: {
    raw,
    cleaned,
    parsed,           // will be an object if valid JSON
    ok: parsed !== null
  }
}];
